    <section className="hero panel"><div className="hero-image"><img src="/iks_hero_banner_1790916915515.jpg" alt="Indian knowledge heritage"/><div className="hero-geometry"><SacredGeometry/></div></div>    <div className="hero-copy"><span className="eyebrow">IKSPHERE • {new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span><h1>{t('Learn the knowledge traditions of India.')}</h1><p>{t('Study mathematics, astronomy, health traditions, metallurgy, architecture, philosophy, linguistics, agriculture and water systems—with historical nuance.')}</p><div className="hero-actions"><button className="primary" onClick={()=>firstIncomplete?open('lesson',firstIncomplete.l.id):setPage('learn')}>{firstIncomplete?<><Play size={16}/>{t('continueLearning')}</>:<><BookOpen size={16}/>{t('learn')}</>}</button><button className="secondary" onClick={()=>setPage('explore')}><Search size={16}/>{t('explore')}</button><button className="secondary" onClick={()=>setPage('learn')}><BookOpen size={16}/>{t('Course syllabus')}</button></div><div className="hero-badges"><span><Sparkles size={14}/> {t('Mobile-first')}</span><span><ShieldCheck size={14}/> {t('Evidence-aware')}</span><span><Brain size={14}/> Groq AI</span></div></div></section>
