function CertificateDownload({cert}){const [busy,setBusy]=useState(false);const download=async()=>{setBusy(true);try{const user=JSON.parse(localStorage.getItem('iksphere_user')||'null');const blob=await api.certificateBlob(cert.id,user.id);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${cert.certificate_no}.pdf`;a.click();URL.revokeObjectURL(url)}catch(e){alert(e.message)}finally{setBusy(false)}};return <button className="secondary" onClick={download} disabled={busy}>{busy?<LoaderCircle className="spin" size={14}/>:<Download size={14}/>} PDF</button>}

function InlineMarkdown({text}){
  const parts=[];const pattern=/\*\*(.+?)\*\*|`([^`]+)`|\*([^*]+)\*/g;let cursor=0,match,index=0;
  while((match=pattern.exec(text))){
    if(match.index>cursor)parts.push(text.slice(cursor,match.index));
    if(match[1])parts.push(<strong key={index++}>{match[1]}</strong>);
    else if(match[2])parts.push(<code key={index++}>{match[2]}</code>);
    else parts.push(<em key={index++}>{match[3]}</em>);
    cursor=pattern.lastIndex;
  }
  if(cursor<text.length)parts.push(text.slice(cursor));
  return <>{parts}</>;
}

function MarkdownMessage({content}){
  const normalized=content.replace(/\|\s+\|(?=\s*(?:[-:]|[^\s|-]))/g,'|\n|');
  const lines=normalized.split(/\r?\n/),blocks=[];let index=0;
  const isRuleRow=line=>line.trim().replace(/^\||\|$/g,'').split('|').every(cell=>/^:?-{3,}:?$/.test(cell.trim()));
  const cellsFor=line=>line.trim().replace(/^\||\|$/g,'').split('|').map(cell=>cell.trim());
  while(index<lines.length){
    const line=lines[index].trim();
    if(!line||/^(?:-{3,}|_{3,}|\*{3,})$/.test(line)){index++;continue}
    const heading=line.match(/^(#{1,6})\s+(.+)$/);
    if(heading){const level=Math.min(heading[1].length+2,6);const Tag=`h${level}`;blocks.push(<Tag key={`h-${blocks.length}`}><InlineMarkdown text={heading[2]}/></Tag>);index++;continue}
    const numberedHeading=line.match(/^\d{1,2}[.)]\s+(.{2,100})$/);
    if(numberedHeading&&!/[.!?:;]$/.test(numberedHeading[1])&&(!lines[index+1]?.trim()||/^\s*(?:#{1,6}\s+|\d{1,2}[.)]\s+)/.test(lines[index+1]))){
      blocks.push(<h4 key={`h-${blocks.length}`}><InlineMarkdown text={numberedHeading[1]}/></h4>);index++;continue
    }
    if(line.startsWith('|')&&index+1<lines.length&&isRuleRow(lines[index+1])){
      const header=cellsFor(line);index+=2;const rows=[];
      while(index<lines.length&&lines[index].trim().startsWith('|')&&!isRuleRow(lines[index])){rows.push(cellsFor(lines[index]));index++}
      blocks.push(<div className="chat-table-wrap" key={`table-${blocks.length}`}><table className="chat-table"><thead><tr>{header.map((cell,i)=><th key={i}><InlineMarkdown text={cell}/></th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{header.map((_,j)=><td key={j}><InlineMarkdown text={row[j]||''}/></td>)}</tr>)}</tbody></table></div>);continue
    }
    const quote=line.match(/^>\s?(.*)$/);
    if(quote){const quoteLines=[];while(index<lines.length&&/^>\s?/.test(lines[index].trim()))quoteLines.push(lines[index++].trim().replace(/^>\s?/,'').trim());blocks.push(<blockquote key={`q-${blocks.length}`}><p>{quoteLines.map((text,i)=><React.Fragment key={i}>{i>0&&<br/>}<InlineMarkdown text={text}/></React.Fragment>)}</p></blockquote>);continue}
    const bullet=line.match(/^\s*[-*+]\s+(.+)$/);
    const ordered=line.match(/^\s*\d+[.)]\s+(.+)$/);
    if(bullet||ordered){const orderedList=!!ordered;const items=[];while(index<lines.length){const current=lines[index].match(orderedList?/^\s*\d+[.)]\s+(.+)$/:/^\s*[-*+]\s+(.+)$/);if(!current)break;items.push(current[1]);index++}const Tag=orderedList?'ol':'ul';blocks.push(<Tag key={`list-${blocks.length}`}>{items.map((item,i)=><li key={i}><InlineMarkdown text={item}/></li>)}</Tag>);continue}
    const boldHeading=line.match(/^\*\*(.+)\*\*:?$/);
    if(boldHeading){blocks.push(<h4 key={`h-${blocks.length}`}><InlineMarkdown text={boldHeading[1]}/></h4>);index++;continue}
    const paragraph=[line];index++;
    while(index<lines.length){
      const next=lines[index].trim();
      if(!next||/^(?:-{3,}|_{3,}|\*{3,})$/.test(next)||/^(?:#{1,6}\s+|>\s?|[-*+]\s+|\d+[.)]\s+)/.test(next)||next.startsWith('|'))break;
      paragraph.push(next);index++;
    }
    blocks.push(<p key={`p-${blocks.length}`}>{paragraph.map((text,i)=><React.Fragment key={i}>{i>0&&<br/>}<InlineMarkdown text={text}/></React.Fragment>)}</p>);
  }
  return <div className="chat-markdown">{blocks}</div>;
}

function Mentor({user,notify,language}){
  const welcomeMessage=t('mentorWelcome',language),welcomeRef=useRef(welcomeMessage);
  const historyRef=useRef(null);
  const [messages,setMessages]=useState([{role:'assistant',content:welcomeMessage}]);
  const [input,setInput]=useState('');const [busy,setBusy]=useState(false);
  useEffect(()=>{setMessages(current=>current.length===1&&current[0].role==='assistant'&&current[0].content===welcomeRef.current?[{...current[0],content:welcomeMessage}]:current);welcomeRef.current=welcomeMessage},[welcomeMessage]);
  useEffect(()=>{api.aiHistory(user.id).then(h=>{if(h?.length)setMessages(h.map(x=>({role:x.role,content:x.content}))) }).catch(()=>{})},[user.id]);
  useEffect(()=>{if(historyRef.current)historyRef.current.scrollTop=historyRef.current.scrollHeight},[messages,busy]);
  const ask=async(text=input)=>{if(!text.trim()||busy)return;setInput('');const next=[...messages,{role:'user',content:text.trim()}];setMessages(next);setBusy(true);try{const languageName={en:'English',hi:'Hindi',mr:'Marathi'}[language]||'English';const r=await api.ask(text,`The user is inside the VidyaDhara mobile learning app. Reply in ${languageName} unless the user asks for another language. Explain Sanskrit terms briefly when useful.`,user.id,messages);setMessages(m=>[...m,{role:'assistant',content:r.answer,meta:r.offline?'Offline curated engine':r.model}]);}catch(e){notify(e.message)}finally{setBusy(false)}};
  const suggestions=['Explain śūnya and place value','Help me read this Sanskrit word: gaṇita','How is Aryabhata\'s Earth-rotation model described?','What is the difference between history and modern science?'];
  const clear=async()=>{try{await api.clearAiHistory(user.id);setMessages([{role:'assistant',content:t('mentorCleared',language)}])}catch(e){notify(e.message)}};
  return <div className="page-stack"><SectionTitle eyebrow={t('SAMVADA')} title={t('AI Guru Mentor')} sub={`${t('Groq-powered when configured')} • ${language.toUpperCase()} ${t('interface')}`} action={<button className="secondary" onClick={clear}><Trash2 size={14}/> {t('clear')}</button>}/><div className="mentor panel"><div className="suggestion-row">{suggestions.map(s=><button key={s} onClick={()=>ask(s)}>{t(s)}</button>)}</div><div className="chat-history" ref={historyRef} aria-live="polite">{messages.map((m,i)=><div className={m.role==='assistant'?'chat-msg ai':'chat-msg user'} key={i}><div className="chat-avatar">{m.role==='assistant'?<Brain size={15}/>:<UserRound size={15}/>}</div><div className="chat-bubble"><MarkdownMessage content={m.content}/>{m.meta&&<small>{m.meta}</small>}</div></div>)}{busy&&<div className="chat-msg ai"><div className="chat-avatar"><Brain size={15}/></div><div className="typing">{t('Samvāda is thinking…')} <span/><span/><span/></div></div>}</div><div className="chat-composer"><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask()}}} placeholder={t('Ask anything…')} rows="1"/><button className="primary icon-submit" onClick={()=>ask()} disabled={!input.trim()||busy}><Send size={17}/></button></div></div></div>}

function Notes({notes,bookmarks,open,refresh,notify,user}){return <div className="page-stack"><SectionTitle eyebrow={t('LIBRARY')} title={t('Notes & bookmarks')} sub={t('Keep your study trail linked to lessons.')}/><div className="two-col"><section className="panel"><SectionTitle eyebrow={t('BOOKMARKS')} title={`${bookmarks.length} ${t('saved')}`}/>{bookmarks.map(b=><button key={b.lesson_id} className="mini-row" onClick={()=>open('lesson',b.lesson_id)}><BookmarkCheck size={16}/><span><b>{b.title}</b><small>{b.course_title}</small></span><ChevronRight/></button>)}{!bookmarks.length&&<EmptyState text={t('Bookmark a lesson to see it here.')}/>}</section><section className="panel"><SectionTitle eyebrow={t('NOTES')} title={`${notes.length} ${t('notes')}`}/>{notes.map(n=><div className="note-row" key={n.id}><div><b>{n.lesson_title}</b><small>{n.course_title} • {n.updated_at.slice(0,10)}</small><p>{n.content}</p></div><button className="icon-btn" onClick={async()=>{try{await api.deleteNote(n.id,user.id);refresh();notify(t('Note deleted'))}catch(e){notify(e.message)}}}><Trash2/></button></div>)}{!notes.length&&<EmptyState text={t('Your first lesson note will appear here.')}/>}</section></div></div>}

