function SanskritGuide({notify}){const [data,setData]=useState(null),[error,setError]=useState(''),[playing,setPlaying]=useState('');useEffect(()=>{api.sanskritGuide().then(setData).catch(e=>setError(e.message))},[]);const speak=(script)=>{setPlaying(script);speakSanskrit(script,()=>setPlaying(script),()=>setPlaying(''),message=>{setPlaying('');notify(message)})};return <div className="page-stack"><SectionTitle eyebrow={t('LANGUAGE HELP')} title={t('Sanskrit reading guide')} sub={t('A small pronunciation aid for learners who do not read Devanagari yet.')}/><section className="panel guide-intro"><div className="sanskrit-demo">अ आ इ ई उ ऊ ऋ ए ऐ ओ औ</div><div><b>{t('IAST makes sound differences visible.')}</b><p>{t('ā = long a • ī = long i • ū = long u • ṛ = vocalic r • ś / ṣ = different “sh” sounds • ṃ = nasal marker • ḥ = visarga.')}</p></div></section>{error&&<div className="form-error">{error}</div>}{data&&<><section><SectionTitle eyebrow={t('VOWELS')} title={t('स्वर • vowels')}/><GuideGrid items={data.vowels} playing={playing} onSpeak={speak}/></section><section><SectionTitle eyebrow={t('CONSONANTS')} title={t('व्यञ्जन • consonants')}/><GuideGrid items={data.consonants} playing={playing} onSpeak={speak}/></section><section><SectionTitle eyebrow={t('COMMON TERMS')} title={t('Words you will see in VidyaDhara')}/><GuideGrid items={data.terms} playing={playing} onSpeak={speak}/></section></>}</div>}
