  const [page,setPage]=useState(initialAdminPage),[selected,setSelected]=useState(null),[quizLaunchId,setQuizLaunchId]=useState(null),[quizAssignmentId,setQuizAssignmentId]=useState(null),[theme,setTheme]=usePersistedState('iksphere_theme','light'),[language,setLanguage]=usePersistedState('iksphere_language',getLanguage()),[search,setSearch]=useState(''),[toast,setToast]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[loading,setLoading]=useState(true);
  const [dashboard,setDashboard]=useState(null),[home,setHome]=useState(null),[courses,setCourses]=useState([]),[paths,setPaths]=useState([]),[quizzes,setQuizzes]=useState([]),[scholars,setScholars]=useState([]),[achievements,setAchievements]=useState(null),[analytics,setAnalytics]=useState(null),[bookmarks,setBookmarks]=useState([]),[notes,setNotes]=useState([]),[config,setConfig]=useState(null),[institution,setInstitution]=useState(null);
  const notify=(m)=>{setToast(m);clearTimeout(window.__iksToast);window.__iksToast=setTimeout(()=>setToast(''),2800)};
  const refresh=async()=>{if(user.role==='super_admin'){setLoading(false);return}if(user.role==='institution_admin'){setLoading(false);return}setLoading(true);try{const [d,h,c,p,q,s,a,an,b,n,cfg]=await Promise.all([api.dashboard(user.id),api.home(user.id),api.courses(user.id),api.paths(user.id),api.quizzes(user.id),api.scholars(),api.achievements(user.id),api.analytics(user.id),api.bookmarks(user.id),api.notes(user.id),api.config()]);let translatedCourses=c,translatedPaths=p,translatedQuizzes=q;
    if(language!=='en'){try{const catalog=await api.translationCatalog(user.id,language);const map=(items)=>new Map(items.map(item=>[item.id,item]));const courseMap=map(catalog.courses),pathMap=map(catalog.paths),quizMap=map(catalog.quizzes);translatedCourses=c.map(course=>{const translated=courseMap.get(course.id)||{};const lessonMap=map(translated.lessons||[]);return {...course,...translated,lessons:course.lessons.map(lesson=>({...lesson,...(lessonMap.get(lesson.id)||{})}))}});translatedPaths=p.map(path=>{const translated=pathMap.get(path.id)||{};const translatedCourseMap=map(translated.courses||[]);return {...path,...translated,courses:path.courses.map(item=>({...item,...(translatedCourseMap.get(item.id)||{})}))}});translatedQuizzes=q.map(quiz=>({...quiz,...(quizMap.get(quiz.id)||{})}))}catch(e){notify(e.message)}}
    const translatedDailyQuiz=translatedQuizzes.find(item=>item.id===h?.daily_quiz?.id);if(translatedDailyQuiz)h.daily_quiz={...h.daily_quiz,...translatedDailyQuiz};
    setDashboard(d);setHome(h);setCourses(translatedCourses);setPaths(translatedPaths);setQuizzes(translatedQuizzes);setScholars(s);setAchievements(a);setAnalytics(an);setBookmarks(b);setNotes(n);setConfig(cfg)}catch(e){notify(e.message)}finally{setLoading(false)}};
  useEffect(()=>{refresh()},[user.id,language]);
  useEffect(()=>{let active=true;setInstitution(null);if(!user.institution_id||user.role==='super_admin')return()=>{active=false};api.myInstitution(user.id).then(result=>{if(active)setInstitution(result.institution)}).catch(error=>{if(active)notify(error.message)});return()=>{active=false}},[user.id,user.institution_id,user.role]);
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.removeItem('iksphere_accent');document.documentElement.style.setProperty('--accent',institution?.primary_color||'#c75d0c');document.documentElement.style.setProperty('--indigo',institution?.secondary_color||'#1a237e');document.documentElement.style.colorScheme=theme;document.documentElement.lang=language;document.documentElement.dataset.reduceMotion=localStorage.getItem('iksphere_reduce_motion')==='1'?'1':'0'},[theme,language,institution]);
